joi_block.script:
hold_ticks := 0
if (all(#LivingRoom #MotionSensor).motionSensor_motion ==| false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 600) {
(#Light).light_moveToBrightness(30, 0)
        delay(5 MIN)
(#Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

